script:
(function init() {
  if (!root_element || !root_element.querySelector) {
    setTimeout(init, 100); return;
  }

  var root = root_element;
  var THEME_KEY = 'kiwi_ov_dash_theme';
  var currentPeriod = 'this_year';
  var customDateFrom = '';
  var customDateTo = '';
  var dashData = {};
  var salesChart = null;

  var q  = function (s) { return root.querySelector(s); };
  var qa = function (s) { return root.querySelectorAll(s); };

  var setText = function (id, v) {
    var el = q('#' + id);
    if (el) el.textContent = (v !== null && v !== undefined) ? v : '—';
  };

  var fmt = function (val, currency) {
    if (val === null || val === undefined) return '—';
    if (currency === undefined) currency = true;
    var num = parseFloat(val) || 0;
    if (currency) {
      if (Math.abs(num) >= 1000000) return (num / 1000000).toFixed(2) + 'M';
      if (Math.abs(num) >= 1000)    return (num / 1000).toFixed(1) + 'K';
      return num.toLocaleString('en-AE', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    }
    return num.toLocaleString();
  };

  var getDashEl = function () { return q('#kiwiOvDash') || root; };

  var applyTheme = function (t) {
    var el = getDashEl();
    if (!el || !el.classList) return;
    if (t === 'dark') el.classList.add('dark');
    else el.classList.remove('dark');
  };

  var toggleTheme = function () {
    var el = getDashEl();
    var isDark = !!(el && el.classList && el.classList.contains('dark'));
    var next = isDark ? 'light' : 'dark';
    applyTheme(next);
    try { localStorage.setItem(THEME_KEY, next); } catch (e) {}
  };

  var loadTheme = function () {
    try { var s = localStorage.getItem(THEME_KEY); if (s) { applyTheme(s); return; } } catch (e) {}
    applyTheme('light');
  };

  var setDate = function () {
    var el = q('#kwovDate');
    if (el) el.textContent = new Date().toLocaleDateString('en-US', { weekday: 'short', year: 'numeric', month: 'short', day: 'numeric' });
  };

  var setLoading = function (on) {
    var ids = ['kwov-customers','kwov-suppliers','kwov-received','kwov-profit','kwov-bank','kwov-cash','kwov-payable','kwov-receivable','kwov-bills','kwov-otherincome'];
    ids.forEach(function (id) {
      var el = q('#' + id);
      if (!el) return;
      if (on) { el.textContent = '…'; el.classList.add('kwov-pulse'); }
      else el.classList.remove('kwov-pulse');
    });
    if (on) {
      ['kwov-person-list','kwov-territory-list','kwov-recent-sales','kwov-recent-purchase','kwov-overdue-rec','kwov-overdue-pay'].forEach(function (id) {
        var el = q('#' + id);
        if (el) el.innerHTML = '<div class="kwov-loader">Loading...</div>';
      });
    }
  };

  var getStickyOffset = function () {
    var offset = 0;
    var navbar = document.querySelector('.navbar');
    if (navbar) offset += navbar.getBoundingClientRect().height;
    var pageHead = document.querySelector('.page-head');
    if (pageHead) { var ph = pageHead.getBoundingClientRect(); if (ph.height > 0) offset += ph.height; }
    return Math.max(offset, 16);
  };

  var openModal = function (title, subtitle, bodyHtml, footerHtml) {
    setText('kwovModalTitle', title);
    setText('kwovModalSubtitle', subtitle || '');
    var body = q('#kwovModalBody');
    if (body) body.innerHTML = bodyHtml;
    var footer = q('#kwovModalFooter');
    if (footer) {
      if (footerHtml) { footer.innerHTML = footerHtml; footer.style.display = 'block'; }
      else { footer.innerHTML = ''; footer.style.display = 'none'; }
    }
    var m = q('#kwovModal');
    if (m) {
      var topOffset = getStickyOffset() + 12;
      var box = m.querySelector('.kwov-modal-box');
      if (box) {
        var available = window.innerHeight - topOffset - 24;
        box.style.marginTop = topOffset + 'px';
        box.style.maxHeight = Math.min(available, 700) + 'px';
      }
      m.classList.add('active');
    }
  };

  var closeModal = function () {
    var m = q('#kwovModal');
    if (m) {
      m.classList.remove('active');
      var box = m.querySelector('.kwov-modal-box');
      if (box) { box.style.marginTop = ''; box.style.maxHeight = ''; }
    }
  };

  var bindModalRows = function (selector, doctype) {
    var body = q('#kwovModalBody');
    if (!body) return;
    body.querySelectorAll(selector).forEach(function (row) {
      row.addEventListener('click', function () {
        closeModal();
        frappe.set_route('Form', doctype, row.dataset.name);
      });
    });
  };

  var loadChartJS = function (cb) {
    if (typeof Chart !== 'undefined') { cb(); return; }
    var s = document.createElement('script');
    s.src = 'https://cdnjs.cloudflare.com/ajax/libs/Chart.js/4.4.1/chart.umd.js';
    s.onload = cb;
    document.head.appendChild(s);
  };

  var chartMonthlyData = [];
  var chartDateFrom = '';
  var chartDateTo = '';

  var buildSalesChart = function (monthly) {
    chartMonthlyData = monthly || [];
    var canvas = q('#kwov-sales-chart');
    if (!canvas) return;
    var isDark = getDashEl().classList.contains('dark');
    var gridColor = isDark ? 'rgba(255,255,255,0.06)' : 'rgba(0,0,0,0.06)';
    var tickColor = isDark ? '#4e4a3c' : '#9e9785';

    var filtered = chartMonthlyData;
    if (chartDateFrom || chartDateTo) {
      filtered = chartMonthlyData.filter(function (m) {
        var mk = m.month_key || '';
        if (chartDateFrom && mk < chartDateFrom.substring(0, 7)) return false;
        if (chartDateTo   && mk > chartDateTo.substring(0, 7))   return false;
        return true;
      });
    }

    var labels       = filtered.map(function (m) { return m.month; });
    var salesData    = filtered.map(function (m) { return parseFloat(m.sales)    || 0; });
    var purchaseData = filtered.map(function (m) { return parseFloat(m.purchase) || 0; });

    var filteredSalesTotal    = salesData.reduce(function (s, v) { return s + v; }, 0);
    var filteredPurchaseTotal = purchaseData.reduce(function (s, v) { return s + v; }, 0);
    var filteredProfit = filteredSalesTotal - filteredPurchaseTotal;

    setText('kwov-chart-sales-total',    fmt(filteredSalesTotal));
    setText('kwov-chart-purchase-total', fmt(filteredPurchaseTotal));
    var profEl = q('#kwov-chart-profit-total');
    if (profEl) {
      profEl.textContent = fmt(filteredProfit);
      profEl.style.color = filteredProfit >= 0 ? 'var(--c-green)' : 'var(--c-red)';
    }

    var infoEl = q('#kwov-chart-clicked-info');
    if (infoEl) infoEl.style.display = 'none';

    if (salesChart) { salesChart.destroy(); salesChart = null; }

    salesChart = new Chart(canvas, {
      type: 'bar',
      data: {
        labels: labels,
        datasets: [
          {
            label: 'Sales',
            data: salesData,
            backgroundColor: 'rgba(26,122,74,0.75)',
            borderColor: '#1a7a4a',
            borderWidth: 1,
            borderRadius: 4,
            order: 1
          },
          {
            label: 'Purchase',
            data: purchaseData,
            backgroundColor: 'rgba(146,64,14,0.65)',
            borderColor: '#92400e',
            borderWidth: 1,
            borderRadius: 4,
            order: 2
          }
        ]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        interaction: { mode: 'index', intersect: false },
        plugins: {
          legend: { display: false },
          tooltip: {
            callbacks: {
              title: function (items) { return items[0].label; },
              label: function (ctx) {
                return '  ' + ctx.dataset.label + ': ' + fmt(ctx.parsed.y);
              },
              afterBody: function (items) {
                var s = parseFloat(items[0] ? items[0].parsed.y : 0) || 0;
                var p = parseFloat(items[1] ? items[1].parsed.y : 0) || 0;
                var profit = s - p;
                var margin = s > 0 ? Math.round(profit / s * 100) : 0;
                return ['  ─────────────', '  Profit: ' + fmt(profit) + ' (' + margin + '%)'];
              }
            },
            backgroundColor: function () { return getDashEl().classList.contains('dark') ? '#1d1c17' : '#fff'; },
            titleColor: function () { return getDashEl().classList.contains('dark') ? '#f0ece2' : '#1c1a16'; },
            bodyColor:  function () { return getDashEl().classList.contains('dark') ? '#8a8370' : '#5a5548'; },
            borderColor: function () { return getDashEl().classList.contains('dark') ? '#38352a' : '#e8e5dc'; },
            borderWidth: 1,
            padding: 10,
            cornerRadius: 8
          }
        },
        scales: {
          x: { grid: { display: false }, ticks: { color: tickColor, font: { size: 11 } } },
          y: {
            beginAtZero: true,
            grid: { color: gridColor },
            ticks: { color: tickColor, font: { size: 11 }, callback: function (v) { return fmt(v); } }
          }
        },
        onClick: function (evt, elements) {
          if (!elements || !elements.length) return;
          var idx = elements[0].index;
          var row = filtered[idx];
          if (!row) return;
          var sales    = parseFloat(row.sales)    || 0;
          var purchase = parseFloat(row.purchase) || 0;
          var profit   = sales - purchase;
          var margin   = sales > 0 ? Math.round(profit / sales * 100) : 0;
          var infoEl   = q('#kwov-chart-clicked-info');
          if (!infoEl) return;
          infoEl.innerHTML =
            '<div class="kwov-chart-info-month">' + row.month + '</div>' +
            '<div class="kwov-chart-info-row"><span class="kwov-chart-info-dot" style="background:var(--c-green)"></span><span class="kwov-chart-info-label">Sales</span><span class="kwov-chart-info-val green">' + fmt(sales) + '</span></div>' +
            '<div class="kwov-chart-info-row"><span class="kwov-chart-info-dot" style="background:var(--c-amber)"></span><span class="kwov-chart-info-label">Purchase</span><span class="kwov-chart-info-val amber">' + fmt(purchase) + '</span></div>' +
            '<div class="kwov-chart-info-divider"></div>' +
            '<div class="kwov-chart-info-row"><span class="kwov-chart-info-dot" style="background:var(--c-violet)"></span><span class="kwov-chart-info-label">Profit</span><span class="kwov-chart-info-val" style="color:' + (profit >= 0 ? 'var(--c-green)' : 'var(--c-red)') + '">' + fmt(profit) + '</span></div>' +
            '<div class="kwov-chart-info-row"><span class="kwov-chart-info-dot" style="background:transparent"></span><span class="kwov-chart-info-label">Margin</span><span class="kwov-chart-info-val" style="color:var(--c-violet)">' + margin + '%</span></div>' +
            '<button class="kwov-chart-info-close" id="kwov-chart-info-close-btn">✕</button>';
          infoEl.style.display = 'flex';
          var closeBtn = infoEl.querySelector('#kwov-chart-info-close-btn');
          if (closeBtn) closeBtn.addEventListener('click', function () { infoEl.style.display = 'none'; });
        }
      }
    });
  };

  var showProfitModal = function () {
    var d = dashData;
    var sales = parseFloat(d.total_sales) || 0;
    var purchase = parseFloat(d.total_purchase) || 0;
    var profit = sales - purchase;
    var margin = sales > 0 ? Math.round(profit / sales * 100) : 0;
    var pctPurchase = sales > 0 ? Math.round(purchase / sales * 100) : 0;
    var body =
      '<div class="kwov-detail-grid">' +
        '<div class="kwov-detail-block"><div class="kwov-detail-block-label">Total Sales</div><div class="kwov-detail-block-val" style="color:var(--c-green)">' + fmt(sales) + '</div></div>' +
        '<div class="kwov-detail-block"><div class="kwov-detail-block-label">Total Purchase</div><div class="kwov-detail-block-val" style="color:var(--c-amber)">' + fmt(purchase) + '</div></div>' +
        '<div class="kwov-detail-block"><div class="kwov-detail-block-label">Net Profit</div><div class="kwov-detail-block-val" style="color:' + (profit >= 0 ? 'var(--c-green)' : 'var(--c-red)') + '">' + fmt(profit) + '</div></div>' +
        '<div class="kwov-detail-block"><div class="kwov-detail-block-label">Profit Margin</div><div class="kwov-detail-block-val" style="color:var(--c-violet)">' + margin + '%</div></div>' +
      '</div>' +
      '<div class="kwov-section-divider">Visual Breakdown</div>' +
      '<div class="kwov-cost-bar-row"><div class="kwov-cost-bar-label"><span>Sales</span><span>' + fmt(sales) + '</span></div><div class="kwov-cost-bar-track"><div class="kwov-cost-bar-fill" style="width:100%;background:var(--c-green)"></div></div></div>' +
      '<div class="kwov-cost-bar-row"><div class="kwov-cost-bar-label"><span>Purchase Cost</span><span>' + fmt(purchase) + '</span></div><div class="kwov-cost-bar-track"><div class="kwov-cost-bar-fill" style="width:' + pctPurchase + '%;background:var(--c-amber)"></div></div></div>' +
      '<div class="kwov-cost-bar-row"><div class="kwov-cost-bar-label"><span>Net Profit</span><span>' + fmt(profit) + '</span></div><div class="kwov-cost-bar-track"><div class="kwov-cost-bar-fill" style="width:' + Math.max(0, margin) + '%;background:var(--c-violet)"></div></div></div>';
    openModal('Profit Analysis', (d.period_label || '') + ' · Margin ' + margin + '%', body);
  };

  var showAccountModal = function (type) {
    var accounts = type === 'bank' ? (dashData.bank_accounts || []) : (dashData.cash_accounts || []);
    var total = type === 'bank' ? dashData.bank_total : dashData.cash_total;
    var title = type === 'bank' ? 'Bank Balance' : 'Cash / Petty Cash Balance';
    var body =
      '<div class="kwov-detail-grid">' +
        '<div class="kwov-detail-block"><div class="kwov-detail-block-label">Total</div><div class="kwov-detail-block-val" style="color:var(--c-blue)">' + fmt(total) + '</div></div>' +
        '<div class="kwov-detail-block"><div class="kwov-detail-block-label">Accounts</div><div class="kwov-detail-block-val">' + accounts.length + '</div></div>' +
      '</div>' +
      '<div class="kwov-section-divider">Account Breakdown</div>' +
      (accounts.length ? accounts.map(function (a) {
        return '<div class="kwov-list-row"><div><div class="kwov-list-name">' + (a.account_name || a.name) + '</div><div class="kwov-list-sub">' + a.name + '</div></div><div class="kwov-list-val" style="color:var(--c-blue)">' + fmt(a.balance) + '</div></div>';
      }).join('') : '<div class="kwov-loader">No accounts found</div>');
    openModal(title, 'Account details', body);
  };

  var showPayableModal = function () {
    var d = dashData;
    var all = d.all_payable || [];
    var body =
      '<div class="kwov-detail-grid">' +
        '<div class="kwov-detail-block"><div class="kwov-detail-block-label">Total Outstanding</div><div class="kwov-detail-block-val" style="color:var(--c-red)">' + fmt(d.accounts_payable) + '</div></div>' +
        '<div class="kwov-detail-block"><div class="kwov-detail-block-label">Open Bills</div><div class="kwov-detail-block-val">' + (d.accounts_payable_count || 0) + '</div></div>' +
        '<div class="kwov-detail-block"><div class="kwov-detail-block-label">Overdue Bills</div><div class="kwov-detail-block-val" style="color:var(--c-red)">' + (d.overdue_payable || 0) + '</div></div>' +
        '<div class="kwov-detail-block"><div class="kwov-detail-block-label">Paid Bills</div><div class="kwov-detail-block-val" style="color:var(--c-green)">' + (d.paid_payable || 0) + '</div></div>' +
      '</div>' +
      '<div class="kwov-section-divider">All Unpaid Bills (' + all.length + ')</div>' +
      (all.length ? all.map(function (inv) {
        var isOverdue = inv.due_date && inv.due_date < frappe.datetime.get_today();
        return '<div class="kwov-list-row kwov-pay-row" data-name="' + inv.name + '"><div><div class="kwov-list-name">' + inv.name + '</div><div class="kwov-list-sub">' + (inv.supplier_name || '—') + ' · Due: ' + (inv.due_date || '—') + (isOverdue ? ' <span style="color:var(--c-red);font-size:9px">OVERDUE</span>' : '') + '</div></div><div class="kwov-list-right"><div class="kwov-list-val" style="color:var(--c-red)">' + fmt(inv.outstanding_amount) + '</div></div></div>';
      }).join('') : '<div class="kwov-loader">No outstanding bills</div>');
    openModal('Accounts Payable', fmt(d.accounts_payable) + ' outstanding', body);
    setTimeout(function () { bindModalRows('.kwov-pay-row', 'Purchase Invoice'); }, 50);
  };

  var showReceivableModal = function () {
    var d = dashData;
    var all = d.all_receivable || [];
    var body =
      '<div class="kwov-detail-grid">' +
        '<div class="kwov-detail-block"><div class="kwov-detail-block-label">Total Outstanding</div><div class="kwov-detail-block-val" style="color:var(--c-green)">' + fmt(d.accounts_receivable) + '</div></div>' +
        '<div class="kwov-detail-block"><div class="kwov-detail-block-label">Open Invoices</div><div class="kwov-detail-block-val">' + (d.accounts_receivable_count || 0) + '</div></div>' +
        '<div class="kwov-detail-block"><div class="kwov-detail-block-label">Overdue Invoices</div><div class="kwov-detail-block-val" style="color:var(--c-red)">' + (d.overdue_receivable || 0) + '</div></div>' +
        '<div class="kwov-detail-block"><div class="kwov-detail-block-label">Paid Invoices</div><div class="kwov-detail-block-val" style="color:var(--c-green)">' + (d.paid_receivable || 0) + '</div></div>' +
      '</div>' +
      '<div class="kwov-section-divider">All Unpaid Invoices (' + all.length + ')</div>' +
      (all.length ? all.map(function (inv) {
        var isOverdue = inv.due_date && inv.due_date < frappe.datetime.get_today();
        return '<div class="kwov-list-row kwov-rec-row" data-name="' + inv.name + '"><div><div class="kwov-list-name">' + inv.name + '</div><div class="kwov-list-sub">' + (inv.customer_name || '—') + ' · Due: ' + (inv.due_date || '—') + (isOverdue ? ' <span style="color:var(--c-red);font-size:9px">OVERDUE</span>' : '') + '</div></div><div class="kwov-list-right"><div class="kwov-list-val" style="color:var(--c-green)">' + fmt(inv.outstanding_amount) + '</div></div></div>';
      }).join('') : '<div class="kwov-loader">No outstanding invoices</div>');
    openModal('Accounts Receivable', fmt(d.accounts_receivable) + ' outstanding', body);
    setTimeout(function () { bindModalRows('.kwov-rec-row', 'Sales Invoice'); }, 50);
  };

  var showBillsModal = function () {
    var d = dashData;
    var records = d.bills_records || [];
    var body =
      '<div class="kwov-detail-grid">' +
        '<div class="kwov-detail-block"><div class="kwov-detail-block-label">Total Unpaid</div><div class="kwov-detail-block-val" style="color:var(--c-amber)">' + fmt(d.bills_payable) + '</div></div>' +
        '<div class="kwov-detail-block"><div class="kwov-detail-block-label">Bills</div><div class="kwov-detail-block-val">' + (d.bills_count || 0) + '</div></div>' +
      '</div>' +
      '<div class="kwov-section-divider">Unpaid Expense Entries</div>' +
      (records.length ? records.map(function (r) {
        return '<div class="kwov-list-row kwov-bill-row" data-name="' + r.name + '"><div><div class="kwov-list-name">' + r.name + '</div><div class="kwov-list-sub">' + (r.posting_date || '') + '</div></div><div class="kwov-list-val" style="color:var(--c-amber)">' + fmt(r.grand_total) + '</div></div>';
      }).join('') : '<div class="kwov-loader">No unpaid bills 🎉</div>');
    openModal('Unpaid Bills (Expense Entries)', fmt(d.bills_payable) + ' · ' + (d.bills_count || 0) + ' bills', body, '<button class="kwov-open-btn" id="kwov-open-bills-modal">Open Expense Entries ↗</button>');
    setTimeout(function () {
      var btn = q('#kwov-open-bills-modal');
      if (btn) btn.addEventListener('click', function () { closeModal(); frappe.set_route('List', 'Expense Entry', { status: 'Unpaid' }); });
      bindModalRows('.kwov-bill-row', 'Expense Entry');
    }, 50);
  };

  var showOtherIncomeModal = function () {
    var d = dashData;
    var records = d.other_income_records || [];
    var body =
      '<div class="kwov-detail-grid">' +
        '<div class="kwov-detail-block"><div class="kwov-detail-block-label">Total Pending</div><div class="kwov-detail-block-val" style="color:var(--c-green)">' + fmt(d.other_income_pending) + '</div></div>' +
        '<div class="kwov-detail-block"><div class="kwov-detail-block-label">Records</div><div class="kwov-detail-block-val">' + (d.other_income_count || 0) + '</div></div>' +
      '</div>' +
      '<div class="kwov-section-divider">Pending Other Income</div>' +
      (records.length ? records.map(function (r) {
        return '<div class="kwov-list-row kwov-oi-row" data-name="' + r.name + '"><div><div class="kwov-list-name">' + r.name + '</div><div class="kwov-list-sub">' + (r.posting_date || '') + '</div></div><div class="kwov-list-val" style="color:var(--c-green)">' + fmt(r.grand_total) + '</div></div>';
      }).join('') : '<div class="kwov-loader">Nothing pending</div>');
    openModal('Other Income Pending', fmt(d.other_income_pending) + ' · ' + (d.other_income_count || 0) + ' records', body, '<button class="kwov-open-btn" id="kwov-open-oi-modal">Open Other Income ↗</button>');
    setTimeout(function () {
      var btn = q('#kwov-open-oi-modal');
      if (btn) btn.addEventListener('click', function () { closeModal(); frappe.set_route('List', 'Other Income', { status: 'Unpaid' }); });
      bindModalRows('.kwov-oi-row', 'Other Income');
    }, 50);
  };

  var populateKPIs = function (d) {
    setText('kwov-customers', fmt(d.total_customers, false));
    setText('kwov-suppliers', fmt(d.total_suppliers, false));
    setText('kwov-received', fmt(d.total_received));
    setText('kwov-received-sub', d.period_label || 'Period');
    var profit = (parseFloat(d.total_sales) || 0) - (parseFloat(d.total_purchase) || 0);
    var profEl = q('#kwov-profit');
    if (profEl) { profEl.textContent = fmt(profit); profEl.style.color = profit >= 0 ? 'var(--c-green)' : 'var(--c-red)'; }
    setText('kwov-chart-sales-total', fmt(d.total_sales));
    setText('kwov-chart-purchase-total', fmt(d.total_purchase));
  };

  var renderAccList = function (containerId, accounts) {
    var el = q('#' + containerId);
    if (!el) return;
    el.innerHTML = (accounts || []).slice(0, 3).map(function (a) {
      return '<div class="kwov-bal-acc-row"><span class="kwov-bal-acc-name">' + (a.account_name || a.name) + '</span><span class="kwov-bal-acc-amt">' + fmt(a.balance) + '</span></div>';
    }).join('') || '<div class="kwov-bal-acc-row"><span class="kwov-bal-acc-name" style="color:var(--text-3)">No accounts</span></div>';
  };

  var populateBalances = function (d) {
    setText('kwov-bank', fmt(d.bank_total));
    setText('kwov-cash', fmt(d.cash_total));
    setText('kwov-payable', fmt(d.accounts_payable));
    setText('kwov-receivable', fmt(d.accounts_receivable));
    setText('kwov-payable-meta', (d.accounts_payable_count || 0) + ' open · ' + (d.overdue_payable || 0) + ' overdue · ' + (d.paid_payable || 0) + ' paid');
    setText('kwov-receivable-meta', (d.accounts_receivable_count || 0) + ' open · ' + (d.overdue_receivable || 0) + ' overdue · ' + (d.paid_receivable || 0) + ' paid');
    renderAccList('kwov-bank-list', d.bank_accounts);
    renderAccList('kwov-cash-list', d.cash_accounts);
  };

  var populateBillsAndOtherIncome = function (d) {
    setText('kwov-bills', fmt(d.bills_payable));
    setText('kwov-bills-sub', (d.bills_count || 0) + ' unpaid bills');
    setText('kwov-otherincome', fmt(d.other_income_pending));
    setText('kwov-otherincome-sub', (d.other_income_count || 0) + ' pending');
  };

  var populatePersonList = function (rows) {
    var el = q('#kwov-person-list');
    if (!el) return;
    if (!rows || !rows.length) { el.innerHTML = '<div class="kwov-loader">No data for this period</div>'; return; }
    var max = Math.max.apply(null, rows.map(function (r) { return parseFloat(r.total) || 0; }));
    el.innerHTML = rows.map(function (r, idx) {
      var pct = max > 0 ? Math.round((parseFloat(r.total) || 0) / max * 100) : 0;
      return '<div class="kwov-type-row" data-idx="' + idx + '"><div class="kwov-type-dot" style="background:var(--c-blue)"></div><span class="kwov-type-name">' + (r.person_name || 'Unassigned') + '</span><div class="kwov-type-bar-wrap"><div class="kwov-type-bar" style="width:' + pct + '%;background:var(--c-blue)"></div></div><span class="kwov-type-amount">' + fmt(r.total) + '</span><span class="kwov-type-count">' + (r.count || 0) + '</span></div>';
    }).join('');
    el.querySelectorAll('.kwov-type-row').forEach(function (row) {
      row.addEventListener('click', function () {
        var idx = parseInt(row.dataset.idx, 10);
        var r = (dashData.sales_by_person || [])[idx];
        if (!r) return;
        var invRows = (r.invoices || []).map(function (inv) {
          return '<div class="kwov-list-row kwov-person-inv-row" data-name="' + inv.name + '"><div><div class="kwov-list-name">' + inv.name + '</div><div class="kwov-list-sub">' + (inv.customer_name || '—') + ' · ' + (inv.posting_date || '') + '</div></div><div class="kwov-list-val" style="color:var(--c-blue)">' + fmt(inv.grand_total) + '</div></div>';
        }).join('') || '<div class="kwov-loader">No invoices</div>';
        openModal(r.person_name || 'Unassigned', fmt(r.total) + ' · ' + (r.count || 0) + ' invoices', invRows);
        setTimeout(function () { bindModalRows('.kwov-person-inv-row', 'Sales Invoice'); }, 50);
      });
    });
  };

  var populateTerritoryList = function (rows) {
    var el = q('#kwov-territory-list');
    if (!el) return;
    if (!rows || !rows.length) { el.innerHTML = '<div class="kwov-loader">No data for this period</div>'; return; }
    var max = Math.max.apply(null, rows.map(function (r) { return parseFloat(r.total) || 0; }));
    el.innerHTML = rows.map(function (r, idx) {
      var pct = max > 0 ? Math.round((parseFloat(r.total) || 0) / max * 100) : 0;
      return '<div class="kwov-pt-row" data-idx="' + idx + '"><div class="kwov-type-dot" style="background:var(--c-teal)"></div><span class="kwov-pt-name">' + (r.territory || 'Unassigned') + '</span><div class="kwov-pt-bar-wrap"><div class="kwov-pt-bar" style="width:' + pct + '%;background:var(--c-teal)"></div></div><span class="kwov-pt-amount">' + fmt(r.total) + '</span><span class="kwov-pt-count">' + (r.count || 0) + '</span></div>';
    }).join('');
    el.querySelectorAll('.kwov-pt-row').forEach(function (row) {
      row.addEventListener('click', function () {
        var idx = parseInt(row.dataset.idx, 10);
        var r = (dashData.sales_by_territory || [])[idx];
        if (!r) return;
        var invRows = (r.invoices || []).map(function (inv) {
          return '<div class="kwov-list-row kwov-terr-inv-row" data-name="' + inv.name + '"><div><div class="kwov-list-name">' + inv.name + '</div><div class="kwov-list-sub">' + (inv.customer_name || '—') + ' · ' + (inv.posting_date || '') + '</div></div><div class="kwov-list-val" style="color:var(--c-teal)">' + fmt(inv.grand_total) + '</div></div>';
        }).join('') || '<div class="kwov-loader">No invoices</div>';
        openModal(r.territory || 'Unassigned', fmt(r.total) + ' · ' + (r.count || 0) + ' invoices', invRows);
        setTimeout(function () { bindModalRows('.kwov-terr-inv-row', 'Sales Invoice'); }, 50);
      });
    });
  };

  var populateRecentSales = function (invoices) {
    var el = q('#kwov-recent-sales');
    if (!el) return;
    if (!invoices || !invoices.length) { el.innerHTML = '<div class="kwov-loader">No invoices found</div>'; return; }
    el.innerHTML = invoices.slice(0, 6).map(function (inv) {
      return '<div class="kwov-list-row kwov-rs-row" data-name="' + inv.name + '"><div><div class="kwov-list-name">' + inv.name + '</div><div class="kwov-list-sub">' + (inv.customer_name || '—') + ' · ' + (inv.posting_date || '') + (inv.territory ? ' · ' + inv.territory : '') + '</div></div><div class="kwov-list-right"><div class="kwov-list-val" style="color:var(--c-green)">' + fmt(inv.grand_total) + '</div></div></div>';
    }).join('') + (invoices.length > 6 ? '<div class="kwov-show-more" id="kwov-rs-more">View All ' + invoices.length + ' Invoices →</div>' : '');
    el.querySelectorAll('.kwov-rs-row').forEach(function (row) {
      row.addEventListener('click', function () { frappe.set_route('Form', 'Sales Invoice', row.dataset.name); });
    });
    var more = q('#kwov-rs-more');
    if (more) more.addEventListener('click', function () {
      var allRows = invoices.map(function (inv) {
        return '<div class="kwov-list-row kwov-rs-all-row" data-name="' + inv.name + '"><div><div class="kwov-list-name">' + inv.name + '</div><div class="kwov-list-sub">' + (inv.customer_name || '—') + ' · ' + (inv.posting_date || '') + '</div></div><div class="kwov-list-right"><div class="kwov-list-val" style="color:var(--c-green)">' + fmt(inv.grand_total) + '</div></div></div>';
      }).join('');
      openModal('Recent Sales Invoices', invoices.length + ' invoices', allRows);
      setTimeout(function () { bindModalRows('.kwov-rs-all-row', 'Sales Invoice'); }, 50);
    });
  };

  var populateRecentPurchase = function (invoices) {
    var el = q('#kwov-recent-purchase');
    if (!el) return;
    if (!invoices || !invoices.length) { el.innerHTML = '<div class="kwov-loader">No invoices found</div>'; return; }
    el.innerHTML = invoices.slice(0, 6).map(function (inv) {
      return '<div class="kwov-list-row kwov-rp-row" data-name="' + inv.name + '"><div><div class="kwov-list-name">' + inv.name + '</div><div class="kwov-list-sub">' + (inv.supplier_name || '—') + ' · ' + (inv.posting_date || '') + '</div></div><div class="kwov-list-right"><div class="kwov-list-val" style="color:var(--c-amber)">' + fmt(inv.grand_total) + '</div><div style="font-family:JetBrains Mono,monospace;font-size:9px;color:var(--text-3);margin-top:2px">' + (inv.status || '') + '</div></div></div>';
    }).join('') + (invoices.length > 6 ? '<div class="kwov-show-more" id="kwov-rp-more">View All ' + invoices.length + ' Invoices →</div>' : '');
    el.querySelectorAll('.kwov-rp-row').forEach(function (row) {
      row.addEventListener('click', function () { frappe.set_route('Form', 'Purchase Invoice', row.dataset.name); });
    });
    var more = q('#kwov-rp-more');
    if (more) more.addEventListener('click', function () {
      var allRows = invoices.map(function (inv) {
        return '<div class="kwov-list-row kwov-rp-all-row" data-name="' + inv.name + '"><div><div class="kwov-list-name">' + inv.name + '</div><div class="kwov-list-sub">' + (inv.supplier_name || '—') + ' · ' + (inv.posting_date || '') + '</div></div><div class="kwov-list-right"><div class="kwov-list-val" style="color:var(--c-amber)">' + fmt(inv.grand_total) + '</div></div></div>';
      }).join('');
      openModal('Recent Purchase Invoices', invoices.length + ' invoices', allRows);
      setTimeout(function () { bindModalRows('.kwov-rp-all-row', 'Purchase Invoice'); }, 50);
    });
  };

  var populateOverdueRec = function (items) {
    var el = q('#kwov-overdue-rec');
    if (!el) return;
    if (!items || !items.length) { el.innerHTML = '<div class="kwov-loader">No overdue receivables</div>'; return; }
    el.innerHTML = items.slice(0, 6).map(function (inv) {
      return '<div class="kwov-list-row kwov-or-row" data-name="' + inv.name + '"><div style="flex:1;min-width:0"><div class="kwov-overdue-name">' + (inv.customer_name || '—') + '</div><div class="kwov-overdue-sub">' + inv.name + '</div></div><span class="kwov-overdue-due">Due ' + (inv.due_date || '—') + '</span><span class="kwov-overdue-amt">' + fmt(inv.outstanding_amount) + '</span></div>';
    }).join('') + (items.length > 6 ? '<div class="kwov-show-more" id="kwov-or-more">View All ' + items.length + ' →</div>' : '');
    el.querySelectorAll('.kwov-or-row').forEach(function (row) {
      row.addEventListener('click', function () { frappe.set_route('Form', 'Sales Invoice', row.dataset.name); });
    });
    var more = q('#kwov-or-more');
    if (more) more.addEventListener('click', function () {
      var allRows = items.map(function (inv) {
        return '<div class="kwov-list-row kwov-or-all-row" data-name="' + inv.name + '"><div style="flex:1;min-width:0"><div class="kwov-overdue-name">' + (inv.customer_name || '—') + '</div><div class="kwov-overdue-sub">' + inv.name + '</div></div><span class="kwov-overdue-due">Due ' + (inv.due_date || '—') + '</span><span class="kwov-overdue-amt">' + fmt(inv.outstanding_amount) + '</span></div>';
      }).join('');
      openModal('Overdue Receivables', items.length + ' overdue invoices', allRows);
      setTimeout(function () { bindModalRows('.kwov-or-all-row', 'Sales Invoice'); }, 50);
    });
  };

  var populateOverduePay = function (items) {
    var el = q('#kwov-overdue-pay');
    if (!el) return;
    if (!items || !items.length) { el.innerHTML = '<div class="kwov-loader">No overdue payables</div>'; return; }
    el.innerHTML = items.slice(0, 6).map(function (inv) {
      return '<div class="kwov-list-row kwov-op-row" data-name="' + inv.name + '"><div style="flex:1;min-width:0"><div class="kwov-overdue-name">' + (inv.supplier_name || '—') + '</div><div class="kwov-overdue-sub">' + inv.name + '</div></div><span class="kwov-overdue-due">Due ' + (inv.due_date || '—') + '</span><span class="kwov-overdue-amt">' + fmt(inv.outstanding_amount) + '</span></div>';
    }).join('') + (items.length > 6 ? '<div class="kwov-show-more" id="kwov-op-more">View All ' + items.length + ' →</div>' : '');
    el.querySelectorAll('.kwov-op-row').forEach(function (row) {
      row.addEventListener('click', function () { frappe.set_route('Form', 'Purchase Invoice', row.dataset.name); });
    });
    var more = q('#kwov-op-more');
    if (more) more.addEventListener('click', function () {
      var allRows = items.map(function (inv) {
        return '<div class="kwov-list-row kwov-op-all-row" data-name="' + inv.name + '"><div style="flex:1;min-width:0"><div class="kwov-overdue-name">' + (inv.supplier_name || '—') + '</div><div class="kwov-overdue-sub">' + inv.name + '</div></div><span class="kwov-overdue-due">Due ' + (inv.due_date || '—') + '</span><span class="kwov-overdue-amt">' + fmt(inv.outstanding_amount) + '</span></div>';
      }).join('');
      openModal('Overdue Payables', items.length + ' overdue bills', allRows);
      setTimeout(function () { bindModalRows('.kwov-op-all-row', 'Purchase Invoice'); }, 50);
    });
  };

  var refresh = function () {
    var btn = q('#kwovRefreshBtn');
    if (btn) btn.classList.add('spinning');
    setLoading(true);
    var args = { period: currentPeriod };
    if (currentPeriod === 'custom' && customDateFrom && customDateTo) {
      args.date_from = customDateFrom;
      args.date_to   = customDateTo;
    }
    frappe.call({
      method: 'kiwi_food_stuff.kiwi_food_stuff.accounting_dashboard.get_overview_dashboard_data',
      args: args,
      callback: function (r) {
        if (btn) btn.classList.remove('spinning');
        if (r.exc || !r.message) {
          frappe.msgprint({ title: 'Dashboard Error', message: 'Failed to load data.', indicator: 'red' });
          setLoading(false);
          return;
        }
        dashData = r.message;
        populateKPIs(dashData);
        populateBalances(dashData);
        populateBillsAndOtherIncome(dashData);
        populatePersonList(dashData.sales_by_person);
        populateTerritoryList(dashData.sales_by_territory);
        populateRecentSales(dashData.recent_sales);
        populateRecentPurchase(dashData.recent_purchases);
        populateOverdueRec(dashData.overdue_receivables);
        populateOverduePay(dashData.overdue_payables);
        setLoading(false);
        loadChartJS(function () { buildSalesChart(dashData.monthly_sales_purchase); });
      }
    });
  };

  var attachListeners = function () {
    var refreshBtn = q('#kwovRefreshBtn');
    if (refreshBtn) refreshBtn.addEventListener('click', refresh);

    var themeBtn = q('#kwovThemeBtn');
    if (themeBtn) themeBtn.addEventListener('click', toggleTheme);

    var periodSel = q('#kwovPeriodSelect');
    var dateRange = q('#kwovDateRange');
    if (periodSel) {
      periodSel.addEventListener('change', function () {
        currentPeriod = this.value;
        if (dateRange) dateRange.style.display = currentPeriod === 'custom' ? 'flex' : 'none';
        if (currentPeriod !== 'custom') refresh();
      });
    }

    var applyBtn = q('#kwovDateApply');
    if (applyBtn) applyBtn.addEventListener('click', function () {
      var fromEl = q('#kwovDateFrom');
      var toEl   = q('#kwovDateTo');
      if (!fromEl || !toEl || !fromEl.value || !toEl.value) {
        frappe.msgprint({ title: 'Date Required', message: 'Please select both From and To dates.', indicator: 'orange' }); return;
      }
      customDateFrom = fromEl.value;
      customDateTo   = toEl.value;
      refresh();
    });

    var modal = q('#kwovModal');
    if (modal) modal.addEventListener('click', function (e) { if (e.target === modal) closeModal(); });
    var closeBtn = q('#kwovModalClose');
    if (closeBtn) closeBtn.addEventListener('click', closeModal);

    var kpiCust = q('#kwov-kpi-customers');
    if (kpiCust) kpiCust.addEventListener('click', function () { frappe.set_route('List', 'Customer'); });
    var kpiSupp = q('#kwov-kpi-suppliers');
    if (kpiSupp) kpiSupp.addEventListener('click', function () { frappe.set_route('List', 'Supplier'); });
    var kpiRec = q('#kwov-kpi-received');
    if (kpiRec) kpiRec.addEventListener('click', function () { frappe.set_route('List', 'Payment Entry', { payment_type: 'Receive' }); });
    var kpiProfit = q('#kwov-kpi-profit');
    if (kpiProfit) kpiProfit.addEventListener('click', showProfitModal);

    var balBank = q('#kwov-bal-bank');
    if (balBank) balBank.addEventListener('click', function () { showAccountModal('bank'); });
    var balCash = q('#kwov-bal-cash');
    if (balCash) balCash.addEventListener('click', function () { showAccountModal('cash'); });
    var balPay = q('#kwov-bal-payable');
    if (balPay) balPay.addEventListener('click', showPayableModal);
    var balRec = q('#kwov-bal-receivable');
    if (balRec) balRec.addEventListener('click', showReceivableModal);

    var billsCard = q('#kwov-bills-card');
    if (billsCard) billsCard.addEventListener('click', showBillsModal);
    var oiCard = q('#kwov-otherincome-card');
    if (oiCard) oiCard.addEventListener('click', showOtherIncomeModal);

    var lPerson = q('#kwov-link-person');
    if (lPerson) lPerson.addEventListener('click', function () { frappe.set_route('List', 'Sales Invoice'); });
    var lTerr = q('#kwov-link-territory');
    if (lTerr) lTerr.addEventListener('click', function () { frappe.set_route('List', 'Sales Invoice'); });
    var lSales = q('#kwov-link-sales');
    if (lSales) lSales.addEventListener('click', function () { frappe.set_route('List', 'Sales Invoice'); });
    var lPurch = q('#kwov-link-purchase');
    if (lPurch) lPurch.addEventListener('click', function () { frappe.set_route('List', 'Purchase Invoice'); });
    var lOverRec = q('#kwov-link-overdue-rec');
    if (lOverRec) lOverRec.addEventListener('click', function () { frappe.set_route('List', 'Sales Invoice'); });
    var lOverPay = q('#kwov-link-overdue-pay');
    if (lOverPay) lOverPay.addEventListener('click', function () { frappe.set_route('List', 'Purchase Invoice'); });
  };

  var attachChartFilters = function () {
    var fromEl  = q('#kwovChartFrom');
    var toEl    = q('#kwovChartTo');
    var applyBtn = q('#kwovChartApply');
    var resetBtn = q('#kwovChartReset');

    if (applyBtn) {
      applyBtn.addEventListener('click', function () {
        if (!fromEl || !toEl || !fromEl.value || !toEl.value) {
          frappe.msgprint({ title: 'Date Required', message: 'Please select both From and To dates for the chart.', indicator: 'orange' });
          return;
        }
        chartDateFrom = fromEl.value;
        chartDateTo   = toEl.value;
        buildSalesChart(chartMonthlyData);
      });
    }

    if (resetBtn) {
      resetBtn.addEventListener('click', function () {
        chartDateFrom = '';
        chartDateTo   = '';
        if (fromEl) fromEl.value = '';
        if (toEl)   toEl.value   = '';
        buildSalesChart(chartMonthlyData);
      });
    }
  };

  loadTheme();
  setDate();
  attachListeners();
  attachChartFilters();
  refresh();

})();

style:
@import url('https://fonts.googleapis.com/css2?family=Instrument+Sans:wght@400;500;600;700&family=Instrument+Serif:ital@0;1&family=JetBrains+Mono:wght@400;500;600&display=swap');

.kw-ov-dash {
  --bg: #f5f4f0;
  --surface: #ffffff;
  --surface2: #f9f8f5;
  --border: #e8e5dc;
  --border-md: #d4cfc2;
  --text-1: #1c1a16;
  --text-2: #5a5548;
  --text-3: #9e9785;
  --c-gold: #b8860b;      --c-gold-bg: #fef9ec;
  --c-blue: #1a4fa3;      --c-blue-bg: #eef3fc;
  --c-green: #1a7a4a;     --c-green-bg: #edf8f2;
  --c-red: #9b1c1c;       --c-red-bg: #fef2f2;
  --c-teal: #0f6b6b;      --c-teal-bg: #edfafa;
  --c-violet: #5b21b6;    --c-violet-bg: #f5f3ff;
  --c-amber: #92400e;     --c-amber-bg: #fffbeb;
  --c-slate: #374151;     --c-slate-bg: #f8fafc;
  --shadow: 0 1px 3px rgba(28,26,22,0.08), 0 0 0 1px var(--border);
  --shadow-hover: 0 8px 24px rgba(28,26,22,0.12), 0 0 0 1px var(--border-md);
  --radius: 12px;
  --radius-sm: 8px;
  font-family: 'Instrument Sans', sans-serif;
  background: var(--bg);
  color: var(--text-1);
  padding: 28px 24px;
  min-height: 100vh;
  overflow-x: hidden;
  box-sizing: border-box;
  transition: background 0.3s, color 0.3s;
}

.kw-ov-dash *, .kw-ov-dash *::before, .kw-ov-dash *::after { box-sizing: border-box; }

.kw-ov-dash.dark {
  --bg: #0e0d0b;
  --surface: #161510;
  --surface2: #1d1c17;
  --border: #2a2820;
  --border-md: #38352a;
  --text-1: #f0ece2;
  --text-2: #8a8370;
  --text-3: #4e4a3c;
  --c-gold: #d4a017;      --c-gold-bg: rgba(212,160,23,0.12);
  --c-blue: #4d80d0;      --c-blue-bg: rgba(77,128,208,0.12);
  --c-green: #2ea860;     --c-green-bg: rgba(46,168,96,0.12);
  --c-red: #e05252;       --c-red-bg: rgba(224,82,82,0.12);
  --c-teal: #2ab8b8;      --c-teal-bg: rgba(42,184,184,0.12);
  --c-violet: #9d6ff0;    --c-violet-bg: rgba(157,111,240,0.12);
  --c-amber: #f0a030;     --c-amber-bg: rgba(240,160,48,0.12);
  --c-slate: #94a3b8;     --c-slate-bg: rgba(148,163,184,0.10);
  --shadow: 0 1px 4px rgba(0,0,0,0.4), 0 0 0 1px var(--border);
  --shadow-hover: 0 8px 28px rgba(0,0,0,0.45), 0 0 0 1px var(--border-md);
}

.kwov-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: 24px;
  flex-wrap: wrap;
  gap: 14px;
}

.kwov-title-block {}

.kwov-eyebrow {
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px;
  letter-spacing: 0.22em;
  color: var(--c-gold);
  text-transform: uppercase;
  display: block;
  margin-bottom: 5px;
}

.kwov-title {
  font-family: 'Instrument Serif', serif;
  font-size: 26px;
  font-weight: 400;
  color: var(--text-1);
  margin: 0;
  letter-spacing: -0.01em;
  line-height: 1;
}

.kwov-header-right {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.kwov-date {
  font-family: 'JetBrains Mono', monospace;
  font-size: 11px;
  color: var(--text-3);
}

.kwov-period-select {
  font-family: 'Instrument Sans', sans-serif;
  font-size: 12px;
  font-weight: 500;
  background: var(--surface);
  border: 1px solid var(--border-md);
  color: var(--text-2);
  padding: 6px 10px;
  border-radius: 7px;
  cursor: pointer;
  outline: none;
  transition: border-color 0.2s;
}
.kwov-period-select:focus { border-color: var(--c-gold); }

.kwov-btn {
  display: flex;
  align-items: center;
  gap: 6px;
  background: var(--surface);
  border: 1px solid var(--border-md);
  color: var(--text-2);
  font-family: 'Instrument Sans', sans-serif;
  font-size: 12px;
  font-weight: 600;
  padding: 6px 12px;
  border-radius: 7px;
  cursor: pointer;
  transition: all 0.18s;
}
.kwov-btn:hover { border-color: var(--c-gold); color: var(--c-gold); }

.kwov-date-range { display: flex; align-items: center; gap: 6px; }
.kwov-date-input {
  font-family: 'JetBrains Mono', monospace;
  font-size: 11px;
  background: var(--surface);
  border: 1px solid var(--border-md);
  color: var(--text-1);
  padding: 5px 8px;
  border-radius: 7px;
  outline: none;
  transition: border-color 0.2s;
  cursor: pointer;
}
.kwov-date-input:focus { border-color: var(--c-gold); }
.kwov-date-sep { font-family: 'JetBrains Mono', monospace; font-size: 11px; color: var(--text-3); }
.kwov-apply-btn:hover { background: var(--c-gold); color: #fff; border-color: var(--c-gold); }

.kwov-refresh-btn svg { transition: transform 0.4s; }
.kwov-refresh-btn.spinning svg { animation: kwac-spin 0.6s linear infinite; }
@keyframes kwac-spin { to { transform: rotate(360deg); } }

.kwov-section-label {
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--text-3);
  margin: 22px 0 10px;
  display: flex;
  align-items: center;
  gap: 10px;
}
.kwov-section-label::after {
  content: '';
  flex: 1;
  height: 1px;
  background: var(--border);
}

.kwov-kpi {
  background: var(--surface);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 16px 14px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  position: relative;
  overflow: hidden;
  cursor: pointer;
  transition: box-shadow 0.2s, transform 0.2s;
  min-width: 0;
}
.kwov-kpi:hover { box-shadow: var(--shadow-hover); transform: translateY(-2px); }
.kwov-kpi:active { transform: translateY(0) scale(0.98); }

.kwov-kpi-bar {
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 2px;
  border-radius: var(--radius) var(--radius) 0 0;
}
.kwov-kpi.gold  .kwov-kpi-bar { background: var(--c-gold); }
.kwov-kpi.blue  .kwov-kpi-bar { background: var(--c-blue); }
.kwov-kpi.green .kwov-kpi-bar { background: var(--c-green); }
.kwov-kpi.red   .kwov-kpi-bar { background: var(--c-red); }
.kwov-kpi.teal  .kwov-kpi-bar { background: var(--c-teal); }
.kwov-kpi.violet .kwov-kpi-bar { background: var(--c-violet); }
.kwov-kpi.amber .kwov-kpi-bar { background: var(--c-amber); }

.kwov-kpi-label {
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--text-3);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.kwov-kpi-icon {
  width: 30px;
  height: 30px;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 4px;
  flex-shrink: 0;
}
.kwov-kpi.gold  .kwov-kpi-icon { background: var(--c-gold-bg);   color: var(--c-gold); }
.kwov-kpi.blue  .kwov-kpi-icon { background: var(--c-blue-bg);   color: var(--c-blue); }
.kwov-kpi.green .kwov-kpi-icon { background: var(--c-green-bg);  color: var(--c-green); }
.kwov-kpi.red   .kwov-kpi-icon { background: var(--c-red-bg);    color: var(--c-red); }
.kwov-kpi.teal  .kwov-kpi-icon { background: var(--c-teal-bg);   color: var(--c-teal); }
.kwov-kpi.violet .kwov-kpi-icon { background: var(--c-violet-bg); color: var(--c-violet); }
.kwov-kpi.amber .kwov-kpi-icon { background: var(--c-amber-bg);  color: var(--c-amber); }

.kwov-kpi-val {
  font-family: 'Instrument Serif', serif;
  font-size: 26px;
  color: var(--text-1);
  line-height: 1.1;
  transition: all 0.4s;
}
.kwov-kpi-sub {
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px;
  color: var(--text-3);
  margin-top: 2px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.kwov-kpi-arrow {
  position: absolute;
  right: 10px;
  bottom: 10px;
  font-size: 12px;
  color: var(--text-3);
  opacity: 0;
  transform: translateX(-4px);
  transition: opacity 0.2s, transform 0.2s;
}
.kwov-kpi:hover .kwov-kpi-arrow { opacity: 1; transform: translateX(0); }

.kwov-balance-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
}
@media (max-width: 1100px) { .kwov-balance-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (max-width: 600px)  { .kwov-balance-grid { grid-template-columns: 1fr; } }

.kwov-bal-card {
  background: var(--surface);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 16px;
  cursor: pointer;
  transition: box-shadow 0.2s, transform 0.2s;
}
.kwov-bal-card:hover { box-shadow: var(--shadow-hover); transform: translateY(-1px); }

.kwov-bal-header {
  display: flex;
  align-items: center;
  gap: 9px;
  margin-bottom: 10px;
}
.kwov-bal-icon {
  width: 30px;
  height: 30px;
  border-radius: 7px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.kwov-bal-label {
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-3);
}
.kwov-bal-val {
  font-family: 'Instrument Serif', serif;
  font-size: 22px;
  color: var(--text-1);
  margin-bottom: 8px;
}
.kwov-bal-val.danger  { color: var(--c-red); }
.kwov-bal-val.success { color: var(--c-green); }
.kwov-bal-val.warning { color: var(--c-amber); }
.kwov-bal-meta {
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px;
  color: var(--text-3);
  line-height: 1.6;
}
.kwov-bal-acc-row {
  display: flex;
  justify-content: space-between;
  font-size: 10px;
  font-family: 'JetBrains Mono', monospace;
  padding: 2px 0;
}
.kwov-bal-acc-name { color: var(--text-3); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; max-width: 55%; }
.kwov-bal-acc-amt  { color: var(--text-2); }

.kwov-payable-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}
@media (max-width: 900px) { .kwov-payable-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (max-width: 500px) { .kwov-payable-grid { grid-template-columns: 1fr; } }

.kwov-pay-card {
  background: var(--surface);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 16px;
  cursor: pointer;
  transition: box-shadow 0.2s, transform 0.2s;
  position: relative;
  overflow: hidden;
}
.kwov-pay-card::before {
  content: '';
  position: absolute;
  left: 0; top: 0; bottom: 0;
  width: 3px;
}
.kwov-pay-card.emp-exp::before  { background: var(--c-amber); }
.kwov-pay-card.staff-pay::before { background: var(--c-violet); }
.kwov-pay-card.other::before    { background: var(--c-slate); }
.kwov-pay-card:hover { box-shadow: var(--shadow-hover); transform: translateY(-1px); }

.kwov-pay-label {
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-3);
  margin-bottom: 8px;
}
.kwov-pay-val {
  font-family: 'Instrument Serif', serif;
  font-size: 22px;
  color: var(--c-red);
  margin-bottom: 4px;
}
.kwov-pay-sub {
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px;
  color: var(--text-3);
}

.kwov-two-col {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  margin-top: 0;
}
@media (max-width: 900px) { .kwov-two-col { grid-template-columns: 1fr; } }

.kwov-panel {
  background: var(--surface);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  overflow: hidden;
}
.kwov-panel-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 13px 16px;
  border-bottom: 1px solid var(--border);
  background: var(--surface2);
}
.kwov-panel-title {
  font-size: 12px;
  font-weight: 700;
  color: var(--text-1);
  letter-spacing: -0.01em;
}
.kwov-panel-link {
  font-family: 'JetBrains Mono', monospace;
  font-size: 11px;
  color: var(--c-blue);
  cursor: pointer;
  font-weight: 500;
  text-decoration: none;
  transition: opacity 0.2s;
}
.kwov-panel-link:hover { opacity: 0.65; }
.kwov-panel-body { padding: 6px 0; min-height: 120px; }

.kwov-type-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 16px;
  border-bottom: 1px solid var(--border);
  cursor: pointer;
  transition: background 0.15s;
}
.kwov-type-row:last-child { border-bottom: none; }
.kwov-type-row:hover { background: var(--surface2); }
.kwov-type-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  flex-shrink: 0;
}
.kwov-type-name {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-1);
  min-width: 110px;
  flex-shrink: 0;
}
.kwov-type-bar-wrap { flex: 1; height: 5px; background: var(--border); border-radius: 3px; overflow: hidden; }
.kwov-type-bar { height: 100%; border-radius: 3px; transition: width 0.6s cubic-bezier(0.4,0,0.2,1); }
.kwov-type-amount {
  font-family: 'JetBrains Mono', monospace;
  font-size: 11px;
  color: var(--text-2);
  min-width: 62px;
  text-align: right;
}
.kwov-type-count {
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px;
  color: var(--text-3);
  min-width: 36px;
  text-align: right;
}

.kwov-pt-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 16px;
  border-bottom: 1px solid var(--border);
  cursor: pointer;
  transition: background 0.15s;
}
.kwov-pt-row:last-child { border-bottom: none; }
.kwov-pt-row:hover { background: var(--surface2); }
.kwov-pt-name { font-size: 12px; font-weight: 600; color: var(--text-1); min-width: 90px; flex-shrink: 0; }
.kwov-pt-bar-wrap { flex: 1; height: 5px; background: var(--border); border-radius: 3px; overflow: hidden; }
.kwov-pt-bar { height: 100%; border-radius: 3px; transition: width 0.6s cubic-bezier(0.4,0,0.2,1); }
.kwov-pt-amount { font-family: 'JetBrains Mono', monospace; font-size: 11px; color: var(--text-2); min-width: 62px; text-align: right; }
.kwov-pt-count  { font-family: 'JetBrains Mono', monospace; font-size: 10px; color: var(--text-3); min-width: 36px; text-align: right; }

.kwov-list-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 9px 16px;
  border-bottom: 1px solid var(--border);
  cursor: pointer;
  transition: background 0.12s, padding-left 0.12s;
  border-radius: 4px;
}
.kwov-list-row:last-child { border-bottom: none; }
.kwov-list-row:hover { background: var(--surface2); padding-left: 20px; }
.kwov-list-name {
  font-family: 'JetBrains Mono', monospace;
  font-size: 11px;
  color: var(--c-blue);
  font-weight: 500;
}
.kwov-list-sub { font-size: 11px; color: var(--text-2); margin-top: 1px; }
.kwov-list-right { text-align: right; flex-shrink: 0; margin-left: 12px; }
.kwov-list-val { font-family: 'JetBrains Mono', monospace; font-size: 12px; color: var(--text-2); font-weight: 500; }

.kwov-inv-type-badge {
  font-family: 'JetBrains Mono', monospace;
  font-size: 9px;
  padding: 2px 6px;
  border-radius: 3px;
  background: var(--c-blue-bg);
  color: var(--c-blue);
  display: inline-block;
  margin-top: 2px;
}
.kwov-pay-type-badge {
  font-family: 'JetBrains Mono', monospace;
  font-size: 9px;
  padding: 2px 6px;
  border-radius: 3px;
  display: inline-block;
  margin-top: 2px;
}
.pt-credit  { background: var(--c-blue-bg);   color: var(--c-blue); }
.pt-cash    { background: var(--c-green-bg);  color: var(--c-green); }
.pt-warranty { background: var(--c-amber-bg); color: var(--c-amber); }
.pt-insurance { background: var(--c-teal-bg); color: var(--c-teal); }

.kwov-overdue-row {
  display: flex;
  align-items: center;
  padding: 8px 16px;
  border-bottom: 1px solid var(--border);
  gap: 10px;
  cursor: pointer;
  transition: background 0.15s;
}
.kwov-overdue-row:last-child { border-bottom: none; }
.kwov-overdue-row:hover { background: var(--surface2); }
.kwov-overdue-name { font-size: 12px; font-weight: 600; color: var(--text-1); flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.kwov-overdue-sub  { font-family: 'JetBrains Mono', monospace; font-size: 10px; color: var(--text-3); }
.kwov-overdue-amt  { font-family: 'JetBrains Mono', monospace; font-size: 12px; font-weight: 600; color: var(--c-red); flex-shrink: 0; }
.kwov-overdue-due  { font-family: 'JetBrains Mono', monospace; font-size: 10px; color: var(--text-3); flex-shrink: 0; min-width: 76px; text-align: right; }

.kwov-loader {
  text-align: center;
  padding: 32px;
  color: var(--text-3);
  font-family: 'JetBrains Mono', monospace;
  font-size: 11px;
}

.kwov-pulse { animation: kwac-pulse-anim 1.4s ease-in-out infinite; }
@keyframes kwac-pulse-anim { 0%, 100% { opacity: 1; } 50% { opacity: 0.3; } }

.kwov-show-more {
  text-align: center;
  padding: 9px 16px;
  font-family: 'JetBrains Mono', monospace;
  font-size: 11px;
  font-weight: 600;
  color: var(--c-blue);
  cursor: pointer;
  border-top: 1px solid var(--border);
  transition: background 0.15s;
  user-select: none;
}
.kwov-show-more:hover { background: var(--surface2); }

.kwov-modal-overlay {
  display: none;
  position: fixed;
  inset: 0;
  background: rgba(28,26,22,0.5);
  backdrop-filter: blur(4px);
  z-index: 9999;
  align-items: flex-start;
  justify-content: center;
  overflow-y: auto;
}
.kwov-modal-overlay.active { display: flex; animation: kwac-fade 0.18s ease; }
@keyframes kwac-fade { from { opacity: 0; } to { opacity: 1; } }

.kwov-modal-box {
  background: var(--surface);
  border: 1px solid var(--border-md);
  border-radius: var(--radius);
  width: 620px;
  max-width: 96vw;
  max-height: 80vh;
  display: flex;
  flex-direction: column;
  box-shadow: 0 24px 64px rgba(28,26,22,0.25);
  animation: kwac-slide 0.22s cubic-bezier(0.4,0,0.2,1);
  flex-shrink: 0;
}
@keyframes kwac-slide { from { transform: translateY(16px); opacity: 0; } to { transform: translateY(0); opacity: 1; } }

.kwov-modal-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  padding: 16px 20px;
  border-bottom: 1px solid var(--border);
  background: var(--surface2);
  border-radius: var(--radius) var(--radius) 0 0;
  flex-shrink: 0;
}
.kwov-modal-title {
  font-family: 'Instrument Serif', serif;
  font-size: 16px;
  color: var(--text-1);
}
.kwov-modal-subtitle {
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px;
  color: var(--text-3);
  margin-top: 3px;
}
.kwov-modal-close {
  background: none;
  border: none;
  color: var(--text-3);
  font-size: 16px;
  cursor: pointer;
  width: 28px;
  height: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 6px;
  transition: all 0.15s;
  flex-shrink: 0;
  margin-left: 12px;
}
.kwov-modal-close:hover { background: var(--border); color: var(--text-1); }
.kwov-modal-body { padding: 18px 0 0; overflow-y: auto; flex: 1; min-height: 0; }
.kwov-modal-body .kwov-detail-grid { margin: 0 20px 14px; }
.kwov-modal-body .kwov-section-divider { margin: 12px 20px 8px; font-family: 'JetBrains Mono', monospace; font-size: 10px; color: var(--text-3); text-transform: uppercase; letter-spacing: 0.06em; padding-bottom: 6px; border-bottom: 1px solid var(--border); }
.kwov-modal-body .kwov-list-row { padding: 9px 20px; }
.kwov-modal-body .kwov-loader { padding: 20px; }
.kwov-modal-body .kwov-search-input { margin: 0 20px 10px; width: calc(100% - 40px); }
.kwov-modal-footer { padding: 14px 20px; border-top: 1px solid var(--border); background: var(--surface2); border-radius: 0 0 var(--radius) var(--radius); flex-shrink: 0; }

.kwov-detail-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin-bottom: 14px; }
.kwov-detail-block { background: var(--surface2); border: 1px solid var(--border); border-radius: var(--radius-sm); padding: 10px 12px; }
.kwov-detail-block-label { font-family: 'JetBrains Mono', monospace; font-size: 9px; color: var(--text-3); text-transform: uppercase; letter-spacing: 0.06em; margin-bottom: 4px; }
.kwov-detail-block-val { font-size: 13px; font-weight: 600; color: var(--text-1); }

.kwov-cost-bar-row { margin-bottom: 10px; }
.kwov-cost-bar-label { display: flex; justify-content: space-between; font-size: 11px; color: var(--text-2); margin-bottom: 5px; }
.kwov-cost-bar-label span:last-child { font-family: 'JetBrains Mono', monospace; color: var(--text-1); font-weight: 500; }
.kwov-cost-bar-track { height: 6px; background: var(--border); border-radius: 3px; overflow: hidden; }
.kwov-cost-bar-fill { height: 100%; border-radius: 3px; transition: width 0.5s cubic-bezier(0.4,0,0.2,1); }

.kwov-open-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: var(--c-blue-bg);
  border: 1px solid var(--c-blue);
  color: var(--c-blue);
  font-family: 'Instrument Sans', sans-serif;
  font-size: 12px;
  font-weight: 600;
  padding: 8px 16px;
  border-radius: 7px;
  cursor: pointer;
  transition: all 0.18s;
}
.kwov-open-btn:hover { background: var(--c-blue); color: #fff; }

.kwov-search-input {
  width: 100%;
  padding: 8px 12px;
  margin-bottom: 10px;
  background: var(--surface2);
  border: 1px solid var(--border-md);
  border-radius: 8px;
  color: var(--text-1);
  font-family: 'Instrument Sans', sans-serif;
  font-size: 12px;
  outline: none;
  transition: border-color 0.2s;
  box-sizing: border-box;
}
.kwov-search-input:focus { border-color: var(--c-gold); }
.kwov-search-input::placeholder { color: var(--text-3); }

.kwov-chart-panel {
  background: var(--surface);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 16px 18px 18px;
}

.kwov-chart-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 14px;
  flex-wrap: wrap;
  gap: 10px;
}

.kwov-chart-legend {
  display: flex;
  align-items: center;
  gap: 6px;
}

.kwov-legend-dot {
  width: 9px;
  height: 9px;
  border-radius: 3px;
  flex-shrink: 0;
}

.kwov-legend-label {
  font-family: 'JetBrains Mono', monospace;
  font-size: 11px;
  color: var(--text-2);
}

.kwov-chart-totals {
  display: flex;
  gap: 18px;
}

.kwov-chart-total-item {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
}

.kwov-chart-total-label {
  font-family: 'JetBrains Mono', monospace;
  font-size: 9px;
  color: var(--text-3);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.kwov-chart-total-val {
  font-family: 'Instrument Serif', serif;
  font-size: 16px;
  line-height: 1.2;
}

.kwov-chart-total-val.green { color: var(--c-green); }
.kwov-chart-total-val.amber { color: var(--c-amber); }

.kwov-kpi-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
}
@media (max-width: 1100px) { .kwov-kpi-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (max-width: 560px)  { .kwov-kpi-grid { grid-template-columns: 1fr; } }

.kwov-chart-date-filter {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.kwov-chart-apply-btn {
  font-size: 11px;
  padding: 5px 10px;
  border-radius: 6px;
}

.kwov-chart-apply-btn:hover {
  background: var(--c-gold);
  color: #fff;
  border-color: var(--c-gold);
}

.kwov-chart-reset-btn {
  font-size: 13px;
  padding: 4px 9px;
  border-radius: 6px;
  min-width: 30px;
  justify-content: center;
}

.kwov-chart-reset-btn:hover {
  background: var(--c-red-bg);
  color: var(--c-red);
  border-color: var(--c-red);
}

.kwov-chart-clicked-info {
  display: none;
  align-items: flex-start;
  gap: 16px;
  background: var(--surface2);
  border: 1px solid var(--border-md);
  border-radius: var(--radius-sm);
  padding: 12px 16px;
  margin-bottom: 12px;
  flex-wrap: wrap;
  position: relative;
  animation: kwac-fade 0.15s ease;
}

.kwov-chart-info-month {
  font-family: 'Instrument Serif', serif;
  font-size: 15px;
  color: var(--text-1);
  font-weight: 400;
  min-width: 80px;
  align-self: center;
}

.kwov-chart-info-row {
  display: flex;
  align-items: center;
  gap: 7px;
  min-width: 130px;
}

.kwov-chart-info-dot {
  width: 8px;
  height: 8px;
  border-radius: 3px;
  flex-shrink: 0;
}

.kwov-chart-info-label {
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px;
  color: var(--text-3);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  min-width: 55px;
}

.kwov-chart-info-val {
  font-family: 'JetBrains Mono', monospace;
  font-size: 12px;
  font-weight: 600;
  color: var(--text-1);
}

.kwov-chart-info-val.green { color: var(--c-green); }
.kwov-chart-info-val.amber { color: var(--c-amber); }

.kwov-chart-info-divider {
  width: 1px;
  height: 36px;
  background: var(--border);
  align-self: center;
}

.kwov-chart-info-close {
  position: absolute;
  top: 8px;
  right: 10px;
  background: none;
  border: none;
  color: var(--text-3);
  cursor: pointer;
  font-size: 13px;
  padding: 2px 5px;
  border-radius: 4px;
  transition: all 0.15s;
  line-height: 1;
}

.kwov-chart-info-close:hover {
  background: var(--border);
  color: var(--text-1);
}
